// ai.js
import * as ort from 'onnxruntime-web';

let session = null;

/**
 * ONNX 모델을 로드하고 예측 결과(0~17)를 반환
 * @param {number[]} inputArray - 길이 12의 숫자 배열
 * @returns {Promise<number>} 예측된 행동 인덱스 (0~17)
 */
export async function predict(inputArray) {
  if (!session) {
    session = await ort.InferenceSession.create('../../resources/model/pikachu_ai1.onnx');
  }

  const tensor = new ort.Tensor('float32', Float32Array.from(inputArray), [1, 12]);
  const feeds = {};
  feeds[session.inputNames[0]] = tensor;

  const results = await session.run(feeds);
  const output = results[session.outputNames[0]].data;

  const predicted = output.indexOf(Math.max(...output));
  return predicted;
}
